function featureLink(url){if(clientPreviewRoute(url))return true;if(!connected)return true;const caps=site.manifest.capabilities;return !(/^\/(sports|lotto|poker|fishing|sns|exclusive)(\/|$)/.test(url)||url.includes('leaderboard')&&!caps.leaderboard||url.includes('referral')&&!caps.referral||url.includes('bonuses')&&!caps.bonus||url.startsWith('/casino')&&!D.games.some(g=>g.family==='casino')||url.startsWith('/arcade')&&!D.games.some(g=>g.family==='arcade'));}
function capabilityNotice(title){return '<section class="panel"><h2>'+esc(title)+'</h2><p>'+(!S.signedIn?'Masuk untuk melihat fitur akun ini.':'Fitur ini belum diaktifkan oleh agen.')+'</p>'+(!S.signedIn?'<button class="btn" data-action="auth" data-mode="login">Masuk</button>':'')+'</section>';}
function activeBonuses(){return '<section class="panel"><h2>Bonus tersedia</h2><p>Bonus koin satu kali per kampanye, tanpa syarat wagering. Syarat deposit dan anggaran diperiksa saat klaim.</p>'+((S.rewards||[]).map(c=>`<article class="bonus-card"><h3>${esc(c.title)}</h3><strong>${esc(c.reward)} koin</strong><p>${esc(c.terms)}</p><p>Minimum deposit: ${money(c.min_deposit)} · Sampai ${date(c.ends_at)}</p><button class="btn" data-action="claim-campaign" data-id="${esc(c.id)}" ${c.claimed||BigInt(c.remaining)<BigInt(c.reward)?'disabled':''}>${c.claimed?'Sudah diklaim':BigInt(c.remaining)<BigInt(c.reward)?'Anggaran habis':'Klaim bonus'}</button></article>`).join('')||'<p>Belum ada kampanye yang tersedia.</p>')+'</section>';}
function activeLeaderboard(){if(!S.leaderboard)return capabilityNotice('Leaderboard');return `<section class="panel"><h2>Leaderboard ${esc(S.leaderboard.period)}</h2><p>${esc(S.leaderboard.notice)}</p><div class="table-wrap"><table><thead><tr><th>Peringkat</th><th>Pemain</th><th>Ronde</th><th>Net koin</th></tr></thead><tbody>${S.leaderboard.items.map(r=>`<tr><td>${r.rank}</td><td>${esc(r.name)}${r.self?' (Anda)':''}</td><td>${r.rounds}</td><td>${esc(r.net)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function applyActivation(){
 const settings=site.manifest.settings||{};if(/^#[a-f0-9]{6}$/i.test(settings.accent||''))document.documentElement.style.setProperty('--red',settings.accent);
 if(settings.favicon_url){let icon=document.querySelector('link[rel="icon"]');if(!icon){icon=document.createElement('link');icon.rel='icon';document.head.append(icon);}icon.href=settings.favicon_url;}
 for(const a of document.querySelectorAll('a[data-route]'))if(!featureLink(a.getAttribute('href')||''))a.remove();
 for(const section of document.querySelectorAll('[data-account-panel]'))if(section.dataset.accountPanel==='bonus'&&!site.manifest.capabilities.bonus)section.remove();
 for(const b of document.querySelectorAll('[data-action="freespins"]'))b.remove();
 if(settings.maintenance){const notice=document.createElement('p');notice.className='notice';notice.setAttribute('role','status');notice.textContent=settings.maintenance_message;document.querySelector('#main')?.prepend(notice);for(const b of document.querySelectorAll('[data-action="launch-demo"],[data-action="resume-game"],[data-action="claim-campaign"]'))b.disabled=true;}
}

function save(){try{localStorage.setItem(KEY,JSON.stringify(connected?{version:1,locale:S.locale}:S));}catch{toast('Penyimpanan browser tidak tersedia; data hanya bertahan pada sesi ini.');}}
function log(text){S.activity.unshift({id:id(),text,time:new Date().toISOString()});S.activity=S.activity.slice(0,100);save();}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3500);}
function go(url,options={}){const u=new URL(url,location.origin);if(u.origin!==location.origin)return;if(u.pathname==='/en'){S.locale='en';save();u.pathname='/';}closeModal();history.pushState({},'',u.pathname+u.search+u.hash);pageLimit=30;render();if(options.section&&focusAccountSection(options.section))return;window.scrollTo(0,0);}
