const accountSections=[
 {icon:'user',label:'Informasi',url:'/user',key:'information'},
 {icon:'wallet',label:'Deposit',url:'/deposit',key:'deposit'},
 {icon:'bank',label:'Withdraw',url:'/withdraw/bank-transfer',key:'withdraw'},
 {icon:'gift',label:'Bonus',url:'/user/bonuses',key:'bonus'},
 {icon:'referral',label:'Referral',url:'/user/referral/history',key:'referral'},
 {icon:'mail',label:'Inbox',url:'/user/messages',key:'inbox'},
 {icon:'activity',label:'Aktivitas',url:'/user/activity',key:'activity'},
 {icon:'history',label:'Riwayat',url:'/user/history',key:'history'}
];
function accountTargetFromPath(){
 const p=path();
 if(p==='/deposit')return 'deposit';
 if(p.startsWith('/withdraw'))return 'withdraw';
 if(p.startsWith('/user/bonuses'))return 'bonus';
 if(p.includes('/referral'))return 'referral';
 if(p.startsWith('/user/messages'))return 'inbox';
 if(p.startsWith('/user/activity'))return 'activity';
 if(p.startsWith('/user/history'))return 'history';
 return 'information';
}
function accountLinks(quick=false){
 const currentSection=accountTargetFromPath();
 return accountSections.filter(s=>featureLink(s.url)).map(({icon:name,label,url,key})=>{
  if(!quick)return link(url,icon(name)+esc(t(label)),currentSection===key?'active':'');
  const active=currentSection===key;
  const graphic=`<span class="account-menu-circle">${icon(name)}</span><span class="account-menu-label">${esc(t(label))}</span>`;
  return link(url,graphic,'account-menu-item'+(active?' active':''),`data-account-section="${key}"${active?' aria-current="location"':''}`);
 }).join('');
}
function focusAccountSection(key,scroll=true){
 const node=document.querySelector(`[data-account-panel="${key}"]`);
 if(!node)return false;
 document.querySelectorAll('.account-quick-actions [data-account-section]').forEach(item=>{
  const active=item.dataset.accountSection===key;
  item.classList.toggle('active',active);
  if(active)item.setAttribute('aria-current','location');else item.removeAttribute('aria-current');
 });
 document.querySelectorAll('.account-section').forEach(section=>section.classList.toggle('account-section-active',section===node));
 if(scroll&&typeof node.scrollIntoView==='function'){
  const reduced=typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches;
  node.scrollIntoView({behavior:reduced?'auto':'smooth',block:'start'});
 }
 return true;
}
let accountObserver;
function watchAccountSections(){
 if(accountObserver){accountObserver.disconnect();accountObserver=null;}
 if(path()!=='/user'||typeof IntersectionObserver!=='function')return;
 const sections=[...document.querySelectorAll('.account-hub>.account-section')];
 accountObserver=new IntersectionObserver(entries=>{
  const visible=entries.filter(entry=>entry.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio);
  if(visible[0])focusAccountSection(visible[0].target.dataset.accountPanel,false);
 },{rootMargin:'-18% 0px -55% 0px',threshold:[0,0.15,0.4]});
 sections.forEach(section=>accountObserver.observe(section));
}
function accountPanel(key,html){
 return `<section class="account-section" data-account-panel="${key}" id="account-${key}" tabindex="-1">${html}</section>`;
}
function brandLogo(){if(connected&&(site.manifest.settings?.logo_url||site.manifest.settings?.brand_name)){const s=site.manifest.settings;return link('/',s.logo_url?image(s.logo_url,s.brand_name||site.manifest.tenant.name,'agency-brand-logo'):esc(s.brand_name),'logo','aria-label=+esc(s.brand_name||site.manifest.tenant.name)+');}return link('/',`<span class="brand-wordmark" aria-hidden="true"><span class="brand-number">64</span><span class="brand-letters">COR</span></span>`,'logo','aria-label="64COR"');}
function header(){return `<header class="header"><div class="container header-inner">${brandLogo()}<div class="header-account">${link('/deposit',icon('deposit')+'<span>'+t('Deposit')+'</span>','btn header-deposit')}${link('/user/messages',icon('bell')+(S.signedIn&&S.messages.some(m=>!m.read)?'<span class="notification-dot"></span>':''),'icon-button inbox-button','aria-label="Notifikasi"')}</div></div></header>`;}
