function card(g,featured=false){
 const pinned=softTechFavoriteIds.has(g.id),selected=pinned||S.favorites.includes(g.id);
 const favoriteControl=pinned
  ?`<span class="favorite selected pinned" aria-label="Favorit utama Soft Tech" title="Favorit utama Soft Tech">${icon('star')}</span>`
  :`<button class="favorite ${selected?'selected':''}" data-action="favorite" data-id="${g.id}" aria-label="${selected?'Hapus favorit':'Tambah favorit'} ${esc(g.title)}" aria-pressed="${selected}">${icon('star')}</button>`;
 return `<article class="game-card${g.family==='casino'?' game-card--portrait':''}">${featured?'<span class="hot-badge">HOT</span>':''}${link('/play/'+g.family+'/'+g.id,image(g.image,g.title)+`<span class="game-play">${icon('play')}</span>`,'game-image')}${favoriteControl}${link('/play/'+g.family+'/'+g.id,esc(g.title),'game-name','title="'+esc(g.title)+'"')}</article>`;
}
