function hero(){if(!D.banners.length)return '';return `<div class="hero-layout"><div class="hero-primary"><section class="carousel" aria-label="Promosi utama" aria-roledescription="carousel">${D.banners.map((b,i)=>link(b.path,`<img src="${esc(b.image)}" alt="${esc(b.title||'Banner promosi '+(i+1))}" width="2048" height="683" loading="eager" decoding="async" fetchpriority="${i===0?'high':'low'}">`,'hero-slide '+(String(b.id||'').startsWith('soft-tech')?'hero-original ':'hero-promotion ')+(i===heroIndex?'active':''),'aria-hidden="'+(i!==heroIndex)+'" tabindex="'+(i===heroIndex?'0':'-1')+'"')).join('')}<button class="carousel-arrow prev" data-action="hero-step" data-direction="-1" aria-label="Banner sebelumnya">${icon('left')}</button><button class="carousel-arrow next" data-action="hero-step" data-direction="1" aria-label="Banner berikutnya">${icon('arrow')}</button><div class="dots">${D.banners.map((_,i)=>`<button class="dot ${i===heroIndex?'active':''}" data-action="hero-dot" data-index="${i}" aria-label="Banner ${i+1}" aria-current="${i===heroIndex}"></button>`).join('')}</div></section></div></div>`;}
function promotionCover(p){
 const artwork=p.banner?image(p.banner,p.title,'promotion-banner'): `<div class="promotion-composite"><div class="promotion-copy"><span class="promotion-eyebrow">${t('Promosi')} · GOBI88</span><strong>${esc(p.title)}</strong><span class="promotion-more">Lihat detail ${icon('arrow')}</span></div>${image(p.coverImage,p.title,'promotion-poster')}</div>`;
 return link('/promotions/all/'+p.id,artwork,'promotion-cover','aria-label="'+esc(p.title)+'"');
}
function softTechSection(){return section('Soft Tech','arcade',`<div class="soft-tech-grid">${D.games.filter(g=>g.provider==='soft-tech').map(g=>link('/play/originals/'+g.id,`<span class="soft-tech-art">${image(g.image,g.title)}</span><strong>${esc(g.title)}</strong><span class="soft-tech-label">SOFT TECH ORIGINAL</span>`,'soft-tech-card')).join('')}</div>`,'','home-soft-tech');}
function home(){
 const slots=D.games.filter(g=>g.family==='slot');
 return announcement()+categoryNavigation()+softTechSection()+(!connected||slots.length?section('Hot Slots','hot',`<div class="game-grid">${slots.slice(0,8).map((g,i)=>card(g,i<3)).join('')}</div>`,'/slot/category/hot','home-hot-slots'):'')+section('Promosi','promo',`<div class="promotion-list">${D.promotions.filter(p=>p.coverImage).map(promotionCover).join('')}</div>`,'/promotions/all','home-promotions');
}
const categoryNames={hot:'Hot',exclusive:'Exclusive',new:'New','buy-bonus':'Buy Bonus',table:'Table',megaways:'Megaways','spin-royal':'Spin Royal','level-up':'Level Up',lobby:'Lobby',top:'Top','game-shows':'Game Shows',roulette:'Roulette',baccarat:'Baccarat','sic-bo':'Sic Bo','dragon-tiger':'Dragon Tiger',blackjack:'Blackjack','ball-games':'Ball Games','idn-special':'IDN Special'};
function empty(title='Belum ada data',desc='Coba kategori atau filter lain.',cta=''){return `<div class="empty">${icon('search')}<h3>${t(title)}</h3><p>${desc}</p>${cta}</div>`;}
function searchForm(q=''){return `<form class="search-form" data-form="search"><input name="q" aria-label="${t('Cari permainan')}" placeholder="${t('Cari permainan')}" value="${esc(q)}" maxlength="100"><button class="btn" type="submit">${icon('search')}${t('Cari')}</button></form>`;}
function catalogue(family){
 const pth=path().split('/'),provider=pth[2]==='provider'?pth[3]:null,category=pth[2]==='category'?pth[3]:(family==='casino'?'lobby':'hot'),q=current().searchParams.get('q')||'',fav=current().searchParams.get('favorites')==='1';
 let games=D.games.filter(g=>g.family===family);
 const familyTitle=family==='slot'?'Slots':family==='casino'?'Casino':'Arcade';
 const providerOptions=family==='casino'?[...new Map(games.map(g=>[g.provider,{id:g.provider,name:g.providerName,path:'/casino/provider/'+g.provider}])).values()]:D.providers.filter(p=>p.family===family);
 if(provider)games=games.filter(g=>g.provider===provider);
 if(!provider&&category!=='hot'&&category!=='top'){
  if(category==='lobby')games=games.filter(g=>/lobby/i.test(g.title));
  else if(category==='exclusive'||category==='new'||category==='buy-bonus'||category==='megaways'||category==='level-up')games=games.filter(g=>g.tags.includes(category));
  else if(family==='casino')games=games.filter(g=>g.tags.includes(category)||category==='idn-special'&&g.provider==='idnlive');
  else if(category==='spin-royal')games=games.filter(g=>g.provider==='slotmania');
  else if(category==='table')games=games.filter(g=>/poker/i.test(g.title));
 }
 if(q)games=games.filter(g=>(g.title+' '+g.providerName).toLowerCase().includes(q.toLowerCase()));
 if(fav)games=games.filter(g=>S.favorites.includes(g.id));
 const cats=family==='casino'?['lobby','top','game-shows','roulette','baccarat','sic-bo','dragon-tiger','blackjack','ball-games','idn-special']:family==='slot'?['hot','exclusive','new','buy-bonus','table','megaways','spin-royal','level-up']:['hot','new'];
 const title=provider?(providerOptions.find(p=>p.id===provider)?.name||provider):(categoryNames[category]||familyTitle);
 return `<div class="page-title"><h1>${familyTitle}</h1><span class="muted small-text">${games.length} permainan dalam katalog demo</span></div><div class="catalog-layout"><aside class="catalog-sidebar"><h3>Kategori</h3>${cats.map(c=>link('/'+family+'/category/'+c,categoryNames[c],'side-link '+(!provider&&category===c?'active':''))).join('')}<h3 style="margin-top:20px">Provider</h3>${providerOptions.map(p=>link(p.path,(p.image?image(p.image,p.name):'')+esc(p.name),'side-link '+(provider===p.id?'active':''))).join('')}</aside><div class="catalog-body"><div class="tabs" aria-label="Kategori game">${cats.map(c=>link('/'+family+'/category/'+c,categoryNames[c],'tab '+(!provider&&category===c?'active':''))).join('')}</div><section class="section"><div class="toolbar">${searchForm(q)}<select class="filter-select" aria-label="Filter provider" data-filter-provider data-family="${family}"><option value="">Semua provider</option>${providerOptions.map(p=>`<option value="${esc(p.id)}" ${provider===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><button class="filter-favorites ${fav?'active':''}" data-action="filter-favorites">${icon('star')} ${t('Favorit')}</button></div><div class="catalog-heading"><h2>${esc(title)}</h2><span class="muted small-text">${games.length} hasil</span></div>${games.length?grid(games.slice(0,pageLimit)):empty('Tidak ada permainan','Katalog demo untuk filter ini belum tersedia. Pilih semua kategori untuk melihat game yang sudah disalin.',link('/'+family+'/category/hot','Lihat katalog','btn secondary'))}${games.length>pageLimit?'<div class="loading-more"><button class="btn secondary" data-action="more">Tampilkan lebih banyak</button></div>':''}</section></div></div>`;
}
function searchPage(){const q=current().searchParams.get('q')||'',fav=current().searchParams.get('favorites')==='1';const games=D.games.filter(g=>(!q||(g.title+' '+g.providerName).toLowerCase().includes(q.toLowerCase()))&&(!fav||S.favorites.includes(g.id)));return `<div class="page-title"><h1>${t('Hasil pencarian')}</h1><button class="filter-favorites ${fav?'active':''}" data-action="filter-favorites">${icon('star')} ${t('Favorit')}</button></div><section class="section search-results"><div class="toolbar">${searchForm(q)}</div><p class="load-result">${games.length} permainan ${q?'untuk “'+esc(q)+'”':''}</p>${games.length?grid(games.slice(0,pageLimit)):empty('Tidak ada permainan','Ubah kata kunci atau hapus filter favorit.')}${games.length>pageLimit?'<div class="loading-more"><button class="btn secondary" data-action="more">Tampilkan lebih banyak</button></div>':''}</section>`;}


function sportsPage(){const type=path().split('/')[2]||'',items=D.sports.filter(s=>!type||s.type===type);return `<div class="page-title"><h1>Sports+</h1></div>${image(D.illustrations.sportsHero,'Sportsbook','wide-banner')}<div class="tabs">${[['','Semua'],['sport','Sports'],['esport','E-sports'],['virtual','Virtual']].map(([k,l])=>link('/sports'+(k?'/'+k:''),t(l),'tab '+(type===k?'active':''))).join('')}</div><div class="sports-grid">${items.map(s=>`<article class="sports-card">${image(s.image,s.title)}<div class="card-content"><h3>${esc(s.title)}</h3><button class="btn small" data-action="provider-preview" data-id="${s.id}">Main ${esc(s.title)}</button></div></article>`).join('')}</div>`;}
function exclusivePage(){return `<div class="page-title"><h1>${t('Eksklusif')}</h1></div><section class="section"><div class="exclusive-grid" style="padding-top:16px">${D.exclusive.map(x=>link(x.path,image(x.image,x.title),'','aria-label="'+esc(x.title)+'"')).join('')}</div></section>`;}
function pokerPage(){const games=D.games.filter(g=>g.family==='poker');return `<div class="page-title"><h1>Poker</h1></div>${image(D.illustrations.pokerHero,'Poker','wide-banner')}<div class="panel"><div class="form-actions"><span>Poker Username: <strong>PLAYGROUND_DEMO</strong></span><button class="btn secondary small" data-action="copy" data-value="PLAYGROUND_DEMO">${icon('copy')} Copy</button><button class="btn secondary" data-action="download-info">${icon('download')} Download Aplikasi</button><button class="btn" data-action="poker-preview">Main Sekarang</button><span class="demo-chip">DEMO</span></div></div>${section('Poker','poker',grid(games))}`;}
function fishingPage(){return `<div class="page-title"><h1>Fishing</h1></div><div class="two-col"><section class="panel">${image(D.illustrations.fishing,'Fishing','feature-art')}</section><section class="panel"><h2>Fishing Arcade</h2><p class="muted">Jelajahi permainan fishing dari provider pilihan Anda.</p><p class="notice">Lobby Fishing siap untuk integrasi. Katalog provider belum terhubung dalam pratinjau ini.</p><button class="btn" data-action="fishing-preview">Pratinjau lobby</button><div class="form-actions">${link('/arcade/category/hot','Lihat Arcade','btn secondary')}</div></section></div>`;}
function lottoPage(){const sub=path().split('/')[2]||'popular',historyPage=sub==='results';return `<div class="page-title"><h1>Lotto</h1><span class="demo-chip">DATA CONTOH</span></div><div class="tabs">${[['popular','Populer'],['lotto','Lotto'],['e-lottery','E-Lottery'],['lotteries','Semua'],['results','Histori']].map(([k,l])=>link('/lotto/'+k,t(l),'tab '+(sub===k?'active':''))).join('')}</div>${historyPage?`<div class="panel"><h2>Histori Hasil</h2><form data-form="lotto-history" class="form-actions"><input type="date" name="date" value="2026-11-03" aria-label="Tanggal hasil" style="max-width:200px"><button class="btn secondary">Tampilkan</button></form><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Pasaran</th><th>Hasil contoh</th></tr></thead><tbody id="lotto-history-body">${[3,2,1].map((d,i)=>`<tr><td>${d} November 2026</td><td>Totomacau Pools</td><td>${['8179','4206','9351'][i]} <span class="demo-chip">DEMO</span></td></tr>`).join('')}</tbody></table></div></div>`:`<section class="result-card"><div><h2 style="margin:0;font-size:17px">Totomacau Pools</h2><p class="muted small-text">Hasil contoh · 3 November 2026</p></div><div class="result-digits" aria-label="Hasil contoh 8179"><span>8</span><span>1</span><span>7</span><span>9</span></div><div><div class="small-text muted">Countdown demo</div><strong class="countdown" data-countdown>00:59:59</strong></div>${link('/lotto/results/idn-lotto','Histori hasil','btn secondary')}</section>${section('E-Lottery','lotto',grid(D.games.filter(g=>g.family==='lotto')))}`}`;}
function promotionsPage(){const selected=path().split('/')[3],q=current().searchParams.get('category')||'all';if(selected){const p=D.promotions.find(x=>x.id===selected);if(!p)return notFound();return `<div class="page-title"><h1>${esc(p.title)}</h1>${link('/promotions/all',t('Kembali'),'btn secondary small')}</div><div class="promo-detail"><div>${image(p.banner||p.image,p.title)}</div><section class="panel"><h2>${esc(p.title)}</h2><span class="status">${esc(p.period)}</span><p>${esc(p.summary)}</p><h3>Syarat & Ketentuan</h3><ul>${p.terms.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul><p class="notice">Klaim pada halaman ini merupakan simulasi. Tidak ada bonus atau uang nyata yang diberikan.</p><button class="btn block" data-action="claim-promo" data-id="${p.id}" ${S.claimed.includes(p.id)?'disabled':''}>${S.claimed.includes(p.id)?'Sudah diklaim':'Coba klaim bonus demo'}</button></section></div>`;}
 const list=D.promotions.filter(p=>p.coverImage&&(q==='all'||p.category===q));return `<div class="page-title"><h1>${t('Promosi')}</h1></div><div class="tabs">${[['all','Semua'],['slots','Slots'],['sports','Sports+']].map(([k,l])=>link('/promotions/all?category='+k,t(l),'tab '+(q===k?'active':''))).join('')}</div><section class="section"><div class="promotion-list" style="padding-top:16px">${list.map(promotionCover).join('')}</div></section>`;
}
function leaderboardPage(){if(connected)return activeLeaderboard();return `<div class="page-title"><h1>Leaderboard</h1><span class="demo-chip">SIMULASI</span></div><div class="tabs">${['distributed','weekly','monthly'].map((k,i)=>link('/leaderboard/'+k,['Dibagikan','Mingguan','Bulanan'][i],'tab '+(path().endsWith(k)?'active':''))).join('')}</div><section class="panel"><h2>${icon('trophy')} Peringkat Pemain Demo</h2><p class="muted">Contoh tampilan peringkat. Data live akan diisi oleh sistem Playground.</p><div class="table-wrap"><table><thead><tr><th>Peringkat</th><th>Pemain</th><th>Poin demo</th><th>Hadiah contoh</th></tr></thead><tbody>${['Naga***','Maha***','Bint***','Dewa***','Mega***','Raja***','Sena***','Arka***','Satu***','Bara***'].map((n,i)=>`<tr><td>${i<3?icon('trophy'):''} #${i+1}</td><td>${n}</td><td>${(150000-i*9371).toLocaleString('id-ID')}</td><td>${money(1000000-i*90000)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function walletSummary(){return `<div class="panel wallet-summary"><div><div class="muted small-text">${t('Saldo demo')} <span class="demo-chip">SIMULASI</span></div><div class="wallet-number">${money(S.balance)}</div></div><div class="form-actions">${link('/deposit',icon('wallet')+'Deposit','btn deposit-action')}${link('/withdraw/bank-transfer',icon('bank')+'Withdraw','btn secondary')}</div></div>`;}
function field(label,name,value='',type='text',extra='',prefix='f-'){return `<div class="field"><label for="${prefix}${name}">${esc(label)}</label><input id="${prefix}${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function txTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Transaksi</th><th>Metode</th><th>Nominal</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td>${date(x.createdAt)}</td><td>${x.type==='deposit'?'Deposit':'Withdraw'}</td><td>${esc(x.method)}</td><td>${money(x.amount)}</td><td><span class="status ${x.status}">${{pending:'Menunggu',completed:'Selesai',cancelled:'Dibatalkan'}[x.status]}</span></td><td><button class="text-button" data-action="receipt" data-id="${x.id}">Detail</button></td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada data','Transaksi demo Anda akan muncul di sini.');}
function walletPage(withdraw=false,embedded=false){
 const kind=withdraw?'withdraw':'deposit',prefix='f-'+kind+'-',name=withdraw?'Withdraw':'Deposit';
 const methods=withdraw?['Bank Transfer']:['QRIS','Virtual Account','Bank Transfer Manual'];
 const bankFields=withdraw?`<div class="form-grid"><div class="field"><label for="${prefix}bank">Bank tujuan demo</label><select id="${prefix}bank" name="bank"><option>BCA</option><option>Mandiri</option><option>BNI</option><option>BRI</option></select></div>${field('Nomor rekening demo','account','','text','required pattern="[0-9]{8,16}" inputmode="numeric"',prefix)}</div>`:'';
 return (embedded?'':walletSummary())+`<section class="panel wallet-form-panel" data-wallet-kind="${kind}"><header class="wallet-form-heading"><span class="wallet-form-glyph">${icon(withdraw?'bank':'wallet')}</span><div><h2>${name}</h2><p>${withdraw?'Ajukan penarikan saldo demo':'Tambahkan saldo untuk simulasi permainan'}</p></div></header><p class="notice wallet-notice">${withdraw?'Saldo demo dicadangkan ketika permintaan dibuat.':'Pembayaran disimulasikan. Tidak ada dana, tagihan, atau transaksi perbankan nyata.'}</p><form data-form="transaction" data-type="${kind}"><div class="form-grid"><div class="field"><label for="${prefix}method">Metode ${kind}</label><select id="${prefix}method" name="method">${methods.map(m=>'<option>'+m+'</option>').join('')}</select></div>${field('Nominal (IDR)','amount','','number','required min="10000" max="10000000" step="1" inputmode="numeric" placeholder="Minimal 10.000"',prefix)}</div><div class="amount-header">Pilih nominal cepat</div><div class="amount-options" role="group" aria-label="Pilih nominal demo">${[50000,100000,250000,500000,1000000].map(amount=>`<button type="button" data-action="amount" data-amount="${amount}" aria-pressed="false">${money(amount)}</button>`).join('')}</div>${bankFields}<div class="field"><label for="${prefix}note">Catatan (opsional)</label><input id="${prefix}note" name="note" maxlength="120" placeholder="Catatan transaksi demo"></div><button class="btn deposit-action wallet-submit" type="submit">${withdraw?'Ajukan withdraw demo':'Buat deposit demo'}</button><p class="form-error" role="alert"></p></form></section><section class="panel wallet-history"><h2>Transaksi Terakhir</h2>${txTable(S.transactions.filter(tx=>tx.type===kind).slice(0,5))}</section>`;
}
function favoritesSection(){
 const others=D.games.filter(g=>g.provider!=='soft-tech'&&S.favorites.includes(g.id));
 return `<section class="panel account-favorites"><h2>Favorit Saya</h2><div class="account-favorites-soft" data-favorites-group="soft-tech">${grid(softTechFavorites)}</div>${others.length?`<div class="account-favorites-other" data-favorites-group="provider"><div class="favorite-divider" role="separator"><span>Provider lainnya</span></div>${grid(others)}</div>`:''}</section>`;
}
function profilePage(){if(connected)return walletSummary()+`<section class="panel"><h2>Informasi akun</h2><p>Email: ${S.user.email_verified?'Terverifikasi':'Belum diverifikasi'} ${!S.user.email_verified&&site.manifest.capabilities.email_verification?'<button class="text-button" data-action="verify-email">Verifikasi email</button>':''}</p><form data-form="profile">${field('Nama','name',S.user.name,'text','required maxlength="100"')}${field('Email','email',S.user.email,'email','maxlength="200"')}<button class="btn" type="submit">Simpan</button><button class="btn secondary" type="button" data-action="logout">Keluar</button><p class="form-error"></p></form></section><section class="panel"><h2>Ubah password</h2><form data-form="password">${field('Password saat ini','current_password','','password','required')}${field('Password baru','password','','password','required minlength="15" maxlength="128"')}<button class="btn" type="submit">Ubah password</button><p class="form-error"></p></form></section>`+favoritesSection();return walletSummary()+`<section class="panel"><h2>${t('Informasi')}</h2><form data-form="profile"><p class="auth-note">Gunakan data contoh untuk menguji profil. Perubahan tersimpan di browser ini.</p><div class="form-grid">${field('Username demo','name',S.user.name,'text','required minlength="3" maxlength="24" pattern="[a-zA-Z0-9_]+"') }${field('Email demo','email',S.user.email,'email','required maxlength="100"')}</div><div class="form-actions"><button class="btn" type="submit">${t('Simpan')}</button><button type="button" class="btn secondary" data-action="logout">${t('Keluar')}</button></div><p class="form-error" role="alert"></p></form></section>${favoritesSection()}`;}
function bonusesPage(embedded=false){if(connected)return activeBonuses();return (embedded?'':walletSummary())+`<section class="panel"><h2>Bonus & Free Spins</h2><p class="notice">Bonus ini hanya menambah saldo simulasi di browser Anda.</p><div class="bonus-grid">${[['welcome','Bonus Selamat Datang',25000],['daily','Bonus Harian',10000]].map(([k,l,a])=>`<article class="bonus-card"><h3>${icon('gift')} ${l}</h3><div class="bonus-value">${money(a)}</div><p>Satu kali klaim per data demo.</p><button class="btn" data-action="claim-bonus" data-id="${k}" data-amount="${a}" ${S.claimed.includes(k)?'disabled':''}>${S.claimed.includes(k)?'Sudah diklaim':'Klaim demo'}</button></article>`).join('')}</div><h3 style="margin-top:25px">Free Spins</h3><p class="muted">Tidak ada freespin yang tersedia.</p></section>`;}
function referralPage(){return renderClientPreview('referral');}
function messagesPage(){return `<section class="panel"><h2>Inbox <span class="demo-chip">${S.messages.filter(m=>!m.read).length} UNREAD</span></h2><button class="text-button" data-action="read-all">Tandai semua dibaca</button>${S.messages.map(m=>`<button class="message ${m.read?'':'unread'}" data-action="message" data-id="${m.id}"><div><h3>${esc(m.title)}</h3><p>${esc(m.text.slice(0,90))}…</p></div>${icon('arrow')}</button>`).join('')}</section>`;}
function activityPage(){const kind=current().searchParams.get('type')||'all',status=current().searchParams.get('status')||'all';const rows=S.transactions.filter(x=>(kind==='all'||x.type===kind)&&(status==='all'||x.status===status));return `<section class="panel"><h2>${t('Aktivitas')}</h2><form class="form-actions" data-form="activity-filter"><select name="type" aria-label="Jenis transaksi" style="max-width:190px">${[['all','Semua transaksi'],['deposit','Deposit'],['withdraw','Withdraw']].map(([k,l])=>`<option value="${k}" ${kind===k?'selected':''}>${l}</option>`).join('')}</select><select name="status" aria-label="Status transaksi" style="max-width:180px">${[['all','Semua status'],['pending','Menunggu'],['completed','Selesai'],['cancelled','Dibatalkan']].map(([k,l])=>`<option value="${k}" ${status===k?'selected':''}>${l}</option>`).join('')}</select><button class="btn secondary">Filter</button></form>${txTable(rows)}</section><section class="panel"><h2>${connected?'Aktivitas Akun':'Aktivitas Akun Demo'}</h2>${S.activity.length?`<div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Aktivitas</th></tr></thead><tbody>${S.activity.slice(0,30).map(a=>`<tr><td>${date(a.time)}</td><td>${esc(a.text)}</td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada data',connected?'Aktivitas akun yang tercatat di Playground ditampilkan di sini.':'Aktivitas demo akan ditampilkan setelah Anda mencoba workflow.')}</section>`;}
function historyPage(){if(connected)return `<section class="panel"><h2>Riwayat bermain</h2>${S.rounds?.length?`<div class="table-wrap"><table><thead><tr><th>Game</th><th>Bet</th><th>Payout</th><th>Status</th></tr></thead><tbody>${S.rounds.map(r=>`<tr><td>${esc(r.game)}</td><td>${money(r.stake)}</td><td>${money(r.payout)}</td><td>${esc(r.state)}</td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada ronde','Riwayat berasal dari ledger Playground.')}</section>`;const rows=S.activity.filter(a=>/^(Preview game:|Buka game original:)/.test(a.text));return `<section class="panel"><h2>${t('Riwayat')}</h2><p class="notice">Riwayat ini mencatat pratinjau game. Tidak ada taruhan, kemenangan, atau hasil provider nyata.</p>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Waktu</th><th>Game</th><th>Status</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${date(a.time)}</td><td>${esc(a.text.replace(/^(Preview game:|Buka game original:) /,''))}</td><td><span class="status">Preview</span></td></tr>`).join('')}</tbody></table></div>`:empty('Belum ada data','Buka pratinjau salah satu game untuk mencoba alur histori.',link('/slot/category/hot','Jelajahi game','btn'))}</section>`;}
function memberPage(){
 if(!S.signedIn&&connected)return '<section class="panel"><h2>Akun 64COR</h2><button class="btn" data-action="auth" data-mode="login">Masuk</button><button class="btn secondary" data-action="auth" data-mode="register">Daftar</button></section>';
 if(!S.signedIn)return `<div class="panel">${empty('Akun demo belum masuk','Masuk menggunakan identitas demo untuk mencoba halaman member.','<button class="btn" data-action="auth" data-mode="login">Masuk akun demo</button>')}</div>`;
 const p=path(),isHub=p==='/user';
 const content=isHub?`<div class="account-hub">${accountPanel('information',profilePage())}${accountPanel('deposit',walletPage(false,true))}${accountPanel('withdraw',walletPage(true,true))}${accountPanel('bonus',bonusesPage(true))}${accountPanel('referral',referralPage())}${accountPanel('inbox',messagesPage())}${accountPanel('activity',activityPage())}${accountPanel('history',historyPage())}</div>`:
 accountPanel(accountTargetFromPath(),p==='/deposit'?walletPage():p.startsWith('/withdraw')?walletPage(true):p.includes('/bonuses')?bonusesPage():p.includes('/referral')?referralPage():p.includes('/messages')?messagesPage():p.includes('/activity')?activityPage():p.includes('/history')?historyPage():profilePage());
 return `<div class="page-title"><h1>${t('Akun Saya')}</h1><span class="demo-chip">PLAYGROUND DEMO</span></div><div class="account-layout"><aside class="account-sidebar"><div class="account-avatar">${icon('user')}</div><h3>${esc(S.user.name)}</h3><span class="small-text muted">Member demo</span><nav class="account-links account-quick-actions" aria-label="Menu cepat akun">${accountLinks(true)}</nav></aside><div class="account-content">${content}</div></div>`;
}
const info={
 '/about-us':['Tentang Kami','Playground Agent Frontend adalah template antarmuka yang memadukan katalog permainan, promosi, dan area member dalam satu website responsive.','Pratinjau ini memakai struktur dan aset visual referensi GOBI88. Semua aktivitas akun dan wallet merupakan simulasi lokal, terpisah dari website referensi.'],
 '/legal/responsible-gaming':['Responsible Gaming','Halaman ini adalah contoh struktur informasi untuk template Playground. Pratinjau tidak menyediakan perjudian atau transaksi uang nyata.','Pada layanan terintegrasi, agen perlu menyediakan pengaturan batas, waktu bermain, penghentian akses dan jalur bantuan sesuai kebijakan operasionalnya.'],
 '/legal/terms-and-conditions':['Syarat & Ketentuan','Ini adalah pratinjau frontend, bukan layanan permainan atau pembayaran aktif. Akun, saldo, transaksi dan hadiah yang ditampilkan merupakan data demo.','Konten ketentuan operasional final harus diisi oleh pengelola agen sebelum layanan backend diaktifkan. Tombol dan validasi pada demo bertujuan menguji pengalaman pengguna.'],
 '/legal/privacy-policy':['Kebijakan Privasi','Pratinjau menyimpan data demo seperti favorit, saldo simulasi dan histori pada penyimpanan browser perangkat ini. Form demo tidak mengirim data tersebut ke backend.','Gunakan identitas contoh. Anda dapat menghapus data simulasi melalui tombol Reset data demo di footer. Tidak ada tracker atau widget chat pihak ketiga yang disertakan.']
};
function infoPage(){if(connected){const page=publishedPage(site.manifest,path());return `<div class="page-title"><h1>${esc(page?.title||info[path()][0])}</h1></div><section class="panel info-content">${page?(page.body||'').split('\n').map(p=>'<p>'+esc(p)+'</p>').join(''):'<p>Konten halaman ini belum dipublikasikan oleh agen.</p>'}</section>`;}const row=info[path()];return `<div class="page-title"><h1>${row[0]}</h1></div><section class="panel info-content">${row.slice(1).map(p=>'<p>'+p+'</p>').join('')}<p class="notice">Dokumen contoh template. Konten final mengikuti konfigurasi dan kebijakan agen Playground.</p></section>`;}
function contactPage(complaint=false){if(connected)return `<div class="page-title"><h1>Hubungi 64COR</h1></div><section class="panel"><button class="btn secondary" data-action="chat">Chatvice</button><h2>Tiket bantuan</h2>${S.signedIn?`<form data-form="support">${field('Subjek','subject','','text','required maxlength="200"')}<div class="field"><label>Pesan<textarea name="message" required minlength="10" maxlength="4000"></textarea></label></div><button class="btn" type="submit">Kirim tiket</button><p class="form-error"></p></form>`:'<button class="btn" data-action="auth" data-mode="login">Masuk untuk membuat tiket</button>'}</section>`;return `<div class="page-title"><h1>${complaint?'Pengaduan Konsumen':t('Kontak')}</h1></div>${complaint?'':`<div class="contact-grid"><div class="contact-card">${icon('chat')}<h3>Live Chat</h3><p>Coba percakapan bantuan demo.</p><button class="btn" data-action="chat">Buka Chat</button></div><div class="contact-card">${icon('mail')}<h3>Inbox Member</h3><p>Temukan pesan dan pengumuman.</p>${link('/user/messages','Buka Inbox','btn secondary')}</div><div class="contact-card">${icon('user')}<h3>Pengaduan</h3><p>Simulasikan tiket bantuan.</p>${link('/complaint','Buat Tiket','btn secondary')}</div></div>`}<section class="panel" style="margin-top:16px"><h2>${complaint?'Form Pengaduan':'Hubungi Kami'}</h2><p class="auth-note">Pesan disimpan sebagai tiket demo lokal, tidak dikirim kepada GOBI88 atau pihak lain.</p><form data-form="support"><div class="form-grid">${field('Nama demo','name',S.user.name,'text','required maxlength="50"')}${field('Email demo','email',S.user.email,'email','required maxlength="100"')}</div>${field('Subjek','subject','','text','required maxlength="120"')}<div class="field"><label for="f-message">Pesan</label><textarea id="f-message" name="message" required minlength="10" maxlength="2000" placeholder="Tuliskan contoh pertanyaan atau kendala"></textarea></div><button class="btn" type="submit">Simpan tiket demo</button><p class="form-error" role="alert"></p></form></section>`;}
function originalGamePage(g){const mediaSrc=window.__softTechVideoWarmup?.get(g.video)?.url||g.video;return `<section class="panel original-detail"><video class="original-hero original-video" autoplay muted loop playsinline preload="auto" poster="${esc(g.videoPoster)}" aria-label="${esc(g.title)}"><source src="${esc(mediaSrc)}" data-media-path="${esc(g.video)}" type="video/mp4"></video><div class="original-copy">${connected?`<button class="btn original-play" data-action="resume-game" data-id="${esc(g.id)}" ${g.readiness!=="publishable"||g.status!=="Active"?"disabled":""}>${g.readiness==="publishable"&&g.status==="Active"?"Play":"Belum tersedia"}</button>`:`<a class="btn original-play" href="${esc(g.launchUrl)}" target="_blank" rel="noopener noreferrer" data-original-play="${esc(g.id)}">${icon('play')} Play</a>`}${announcement()}<div class="original-info"><span class="soft-tech-label">SOFT TECH ORIGINAL</span><h2>${esc(g.title)}</h2><p>${esc(g.description)}</p><p class="muted">Game dibuka di website Soft Tech dalam tab baru. Akun dan wallet 64COR belum tersinkron ke game.</p><button class="btn secondary" data-action="favorite" data-id="${g.id}" aria-pressed="${S.favorites.includes(g.id)}">${icon('star')} ${S.favorites.includes(g.id)?'Hapus favorit':'Simpan favorit'}</button></div></div></section>`;}

function gamePage(){const gid=path().split('/').pop(),g=D.games.find(x=>x.id===gid);if(!g)return notFound();if(g.provider==='soft-tech')return originalGamePage(g);return `<div class="page-title"><h1>${esc(g.title)}</h1>${link('/'+(g.family==='slot'?'slot/category/hot':g.family==='casino'?'casino/category/lobby':g.family==='arcade'?'arcade/category/hot':g.family),'Kembali','btn secondary small')}</div><section class="panel provider-game-detail"><div class="preview-game">${image(g.image,g.title)}<h3>${esc(g.title)}</h3><p>${esc(g.providerName)} · <span class="demo-chip">PREVIEW UI</span></p><p>Peluncuran provider belum terhubung. Buka sesi pratinjau untuk mencoba alur dan pencatatan histori.</p><button class="btn" data-action="launch-demo" data-id="${g.id}">${icon('play')} Buka pratinjau demo</button></div></section>${section('Pilihan lainnya',g.family==='slot'?'slots':g.family,grid(D.games.filter(x=>x.family===g.family&&x.id!==g.id).slice(0,8)),'','related-games')}`;}
function notFound(){return '<div class="panel">'+empty('Halaman tidak ditemukan','Gunakan navigasi untuk melanjutkan.',link('/','Kembali ke beranda','btn'))+'</div>';}
function content(){const p=path();const preview=clientPreviewRoute(p);if(preview)return renderClientPreview(preview);if(connected&&['/sports','/lotto','/poker','/fishing','/sns','/exclusive'].some(x=>p===x||p.startsWith(x+'/')))return '<section class="panel"><h1>Belum tersedia</h1><p>Layanan ini belum diaktifkan di Playground.</p></section>';if(p==='/'||p==='/en')return home();if(p.startsWith('/play/'))return gamePage();if(p.startsWith('/slot'))return catalogue('slot');if(p.startsWith('/casino'))return catalogue('casino');if(p.startsWith('/arcade'))return catalogue('arcade');if(p==='/exclusive')return exclusivePage();if(p.startsWith('/sports'))return sportsPage();if(p==='/poker')return pokerPage();if(p.startsWith('/lotto'))return lottoPage();if(p==='/fishing')return fishingPage();if(p.startsWith('/promotions'))return promotionsPage();if(p.startsWith('/leaderboard'))return leaderboardPage();if(p==='/search')return searchPage();if(p.startsWith('/user')||p==='/deposit'||p.startsWith('/withdraw'))return memberPage();if(p==='/referral')return referralPage();if(info[p]||connected&&publishedPage(site.manifest,p)?.genesis_page)return infoPage();if(p==='/contact'||p==='/complaint')return contactPage(p==='/complaint');if(p==='/sns')return `<div class="page-title"><h1>Stream n'Spin</h1></div>${image(D.illustrations.sns,"Stream n'Spin",'wide-banner')}<div class="panel"><h2>Live Stream & Games</h2><p class="muted">Pratinjau tampilan streaming. Flux video live belum terhubung.</p>${link('/slot/category/hot','Jelajahi Slots','btn')}</div>`;if(['/login','/register','/forgot-password'].includes(p))return `<div class="panel"><h1>Akun Demo</h1><button class="btn" data-action="auth" data-mode="${p.slice(1)==='forgot-password'?'forgot':p.slice(1)}">Buka form</button></div>`;return notFound();}
function renderBottomNav(){
 const items=[['home','Beranda','/'],['search','Cari','/search'],['wallet','Deposit','/deposit'],['gift','Promo','/promotions/all'],['user','Akun','/user']];
 const p=path(),index=p==='/'||p==='/en'?0:p==='/deposit'?2:p.startsWith('/promotions')?3:/^\/(user|withdraw|referral|login|register|forgot-password)(\/|$)/.test(p)?4:/^\/(search|slot|casino|arcade|play|poker|lotto|fishing|sports|exclusive)(\/|$)/.test(p)?1:-1;
 const root=document.querySelector('#bottom-nav-root');
 if(!root.firstElementChild)root.innerHTML=`<nav class="mobile-bottom floating-nav" aria-label="Navigasi utama"><span class="nav-indicator" aria-hidden="true"><span class="nav-glass"></span></span>${items.map(([i,label,url])=>link(url,pixelIcon(i)+`<span data-nav-label>${t(label)}</span>`,'dock-link')).join('')}</nav>`;
 const nav=root.firstElementChild,previous=nav.dataset.activeIndex;
 nav.dataset.activeIndex=String(index);nav.style.setProperty('--active-index',String(Math.max(0,index)));
 nav.querySelectorAll('.dock-link').forEach((el,i)=>{el.classList.toggle('active',i===index);el.querySelector('[data-nav-label]').textContent=t(items[i][1]);if(i===index)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});
 const lens=nav.querySelector('.nav-glass');
 if(previous!==undefined&&previous!==String(index)&&index>=0&&!matchMedia('(prefers-reduced-motion: reduce)').matches&&lens.animate){lens.getAnimations().forEach(a=>a.cancel());lens.animate([{transform:'scaleX(1) scaleY(1)'},{transform:'scaleX(1.16) scaleY(.90)',offset:.35},{transform:'scaleX(.97) scaleY(1.03)',offset:.8},{transform:'scaleX(1) scaleY(1)'}],{duration:560,easing:'cubic-bezier(.2,.7,.2,1)'});}
}
function rememberPlayed(g){
 if(!g)return;
 S=rememberGame(S,g.id,new Date().toISOString());save();renderContinuePlaying();
}
function renderContinuePlaying(){
 let root=document.querySelector('#continue-playing-root');
 if(!root){root=document.createElement('div');root.id='continue-playing-root';document.querySelector('#bottom-nav-root').before(root);}
 const g=S.lastPlayed&&!S.lastPlayed.dismissed?D.games.find(g=>g.id===S.lastPlayed.gameId):null;
 document.body.classList.toggle('has-continue-playing',Boolean(g));
 if(!g){root.innerHTML='';delete root.dataset.gameId;return;}
 if(root.dataset.gameId===g.id)return;
 root.dataset.gameId=g.id;
 const play=!connected&&g.launchUrl?`<a class="continue-play" href="${esc(g.launchUrl)}" target="_blank" rel="noopener noreferrer" data-original-play="${esc(g.id)}" aria-label="Lanjutkan ${esc(g.title)}">${icon('play')}</a>`:`<button class="continue-play" data-action="resume-game" data-id="${esc(g.id)}" aria-label="Lanjutkan ${esc(g.title)}">${icon('play')}</button>`;
 root.innerHTML=`<aside class="continue-card" aria-label="Continue Playing">${image(g.image,g.title,'continue-thumbnail',true)}<div class="continue-copy"><span class="continue-eyebrow">CONTINUE PLAYING</span><strong>${esc(g.title)}</strong><span class="continue-provider">${esc(g.providerName)}</span></div><div class="continue-actions"><button class="continue-close" data-action="dismiss-continue" aria-label="Tutup Continue Playing">${icon('close')}</button>${play}</div></aside>`;
}
function render(){if(connected)PG.applyGenesisLocale(D,S.locale);document.documentElement.lang=S.locale;const isHome=path()==='/';const isMember=!clientPreviewRoute(path())&&(path()==='/deposit'||path()==='/user'||path().startsWith('/user/')||path().startsWith('/withdraw'));const isOriginal=path().startsWith('/play/')&&D.games.some(g=>g.provider==='soft-tech'&&g.id===path().split('/').pop());document.body.classList.toggle('original-game-page',isOriginal);app.innerHTML=header()+(isHome?hero():'')+`<main id="main" class="container ${isHome?'home-page':''}">${isHome?'':(isOriginal?'':announcement()+(isMember?'':categoryNavigation()))}${content()}</main>`+footer();if(connected){app.querySelector('[data-action="reset-prompt"]')?.remove();for(const b of app.querySelectorAll('[data-action="claim-promo"]')){const notice=b.previousElementSibling;if(notice?.classList.contains('notice'))notice.textContent='Promo adalah informasi agen. Bonus koin hanya tersedia melalui kampanye dengan anggaran dan syarat yang berlaku.';if(site.manifest.capabilities.bonus){b.outerHTML=link('/user/bonuses','Lihat bonus tersedia','btn block');}else b.remove();}for(const el of app.querySelectorAll('.demo-notice,.demo-chip')){if(el.textContent.includes('GOBI88')||el.textContent.includes('PLAYGROUND DEMO'))el.textContent=config.demoNotice;}const nodes=document.createTreeWalker(app,NodeFilter.SHOW_TEXT);let n;while(n=nodes.nextNode()){n.textContent=n.textContent.replace(/Akun dan wallet 64COR belum tersinkron ke game\./g,'Sesi game dibuka melalui Playground saat game sudah tersedia.').replace(/Game dibuka di website Soft Tech dalam tab baru\./g,'Status game mengikuti Playground.').replace(/Saldo demo/g,'Saldo koin').replace(/Buat deposit demo/g,'Buat deposit').replace(/Ajukan withdraw demo/g,'Ajukan withdraw').replace(/Member demo/g,'Member 64COR').replace(/katalog demo/g,'katalog agen').replace(/GOBI88/g,'64COR');}applyActivation();genesisNavigation(site.manifest);}renderBottomNav();renderContinuePlaying();watchAccountSections();if(path()==='/user'&&location.hash.startsWith('#account-'))focusAccountSection(location.hash.slice(9));document.title=(isOriginal?(D.games.find(g=>g.id===path().split('/').pop())?.title||'Soft Tech'):(app.querySelector('h1')?.textContent||'Selamat Datang'))+' · 64COR';if(connected){const seo=publishedPage(site.manifest,path());if(seo)document.title=seo.title||'64COR';let meta=document.querySelector('meta[name=description]');if(meta)meta.content=seo?.description||'';let canonical=document.querySelector('link[rel=canonical]');if(!canonical){canonical=document.createElement('link');canonical.rel='canonical';document.head.append(canonical);}canonical.href=seo?.canonical||location.origin+location.pathname;}}


function modal(title,html,wide=false,kind=''){closeModal(false);returnFocus=document.activeElement;overlays.innerHTML=`<div class="overlay" data-overlay><section class="dialog ${wide?'wide':''} ${kind}" role="dialog" aria-modal="true" aria-label="${esc(title)}" tabindex="-1"><header class="dialog-head"><h2>${esc(title)}</h2><button class="icon-button" data-action="close" aria-label="${t('Tutup')}">${icon('close')}</button></header><div class="dialog-body">${html}</div></section></div>`;document.body.classList.add('modal-open');overlays.querySelector('input,button,select,textarea')?.focus();}
function closeModal(restore=true){overlays.innerHTML='';document.body.classList.remove('modal-open');if(restore&&returnFocus?.isConnected)returnFocus.focus();}
function drawer(){closeModal(false);returnFocus=document.activeElement;overlays.innerHTML=`<div class="overlay drawer-overlay" data-overlay><aside class="drawer" role="dialog" aria-modal="true" aria-label="Menu utama" tabindex="-1"><div class="drawer-head">${brandLogo()}<button class="icon-button" data-action="close" aria-label="Tutup menu">${icon('close')}</button></div><p class="demo-notice">Playground frontend preview · Demo</p><div class="drawer-categories">${link('/search',pixelIcon('search')+'<span>Cari</span>','nav-item')}${navMarkup()}</div><nav class="account-links">${accountLinks()}<button class="side-link" data-action="freespins">${icon('gift')} Free Spins</button><button class="side-link" data-action="${S.signedIn?'logout':'auth'}" data-mode="login">${icon('logout')} ${t(S.signedIn?'Keluar':'Masuk')}</button></nav>${link('/deposit',icon('wallet')+' Deposit','btn deposit-action block')}<div class="language-picker"><span>Pilih Bahasa:</span><button data-action="locale" data-locale="id" aria-label="Bahasa Indonesia">${image(D.flags.id,'Indonesia')}</button><button data-action="locale" data-locale="en" aria-label="English">${image(D.flags.en,'English')}</button></div></aside></div>`;document.body.classList.add('modal-open');overlays.querySelector('button').focus();}
function auth(mode='login'){
 if(connected){
   if(mode==='forgot')return modal('Pemulihan akun',`<form data-form="recovery">${field('Username','username','','text','required maxlength="64"')}<p>Admin agen akan memverifikasi identitas Anda sebelum memberikan tautan reset. ${site.manifest.capabilities.email_verification?'Panduan dikirim ke email yang sudah terverifikasi bila tersedia.':'Tidak ada email otomatis.'}</p><button class="btn" type="submit">Ajukan pemulihan</button><p class="form-error"></p></form>`);
   return modal(mode==='register'?'Daftar 64COR':'Masuk 64COR',`<form data-form="auth" data-mode="${mode}">${field('Username','username','','text','required minlength="3" maxlength="64" autocomplete="username"')}${field('Password','password','','password','required minlength="15" maxlength="128" autocomplete="'+(mode==='register'?'new-password':'current-password')+'"')}${mode==='register'?field('Konfirmasi password','confirm','','password','required minlength="15" maxlength="128"')+(site.manifest.capabilities.referral?field('Kode referral (opsional)','referral_code',current().searchParams.get('ref')||'','text','maxlength="24"'):''):''}<button class="btn block" type="submit">${mode==='register'?'Daftar':'Masuk'}</button><p class="form-error" role="alert"></p></form><button class="text-button" data-action="auth" data-mode="${mode==='register'?'login':'register'}">${mode==='register'?'Sudah punya akun? Masuk':'Buat akun baru'}</button><button class="text-button" data-action="auth" data-mode="forgot">Lupa password?</button>`);
 }

 const title=mode==='register'?'Daftar Akun Demo':mode==='forgot'?'Lupa Password — Demo':'Masuk Akun Demo';
 modal(title,`<p class="auth-note">Pratinjau Playground. Gunakan data contoh; tidak terhubung ke akun GOBI88. Password tidak disimpan atau dikirim.</p><form data-form="auth" data-mode="${mode}">${mode!=='forgot'?field('Username demo','username',mode==='login'?'playground_demo':'','text','required minlength="3" maxlength="24" pattern="[a-zA-Z0-9_]+" autocomplete="off"'):''}${mode!=='login'?field('Email demo','email',mode==='forgot'?'demo@example.test':'','email','required maxlength="100" autocomplete="off"'):''}${mode!=='forgot'?field(mode==='login'?'Password demo: demo1234':'Password demo','password',mode==='login'?'demo1234':'','password','required minlength="8" maxlength="64" autocomplete="off"'):''}${mode==='register'?field('Konfirmasi password demo','confirm','','password','required minlength="8" maxlength="64" autocomplete="off"'):''}<button class="btn block" type="submit">${mode==='register'?'Buat akun demo':mode==='forgot'?'Simulasikan reset':t('Masuk')}</button><p class="form-error" role="alert"></p></form><div class="auth-switch">${mode==='login'?'<button class="text-button" data-action="auth" data-mode="register">Daftar demo</button> · <button class="text-button" data-action="auth" data-mode="forgot">Lupa password?</button>':'<button class="text-button" data-action="auth" data-mode="login">Kembali ke login</button>'}</div>`);
}
function receipt(txid){
 if(connected){const tx=S.transactions.find(x=>x.id===txid);if(!tx)return;return modal('Detail transaksi',`<p>${esc(tx.id)}</p><h3>${money(tx.amount)}</h3><p>${esc(tx.method)} · <strong>${esc(tx.state)}</strong></p><p>Status berasal dari Playground. ${site.manifest.tenant.environment==='sandbox'?'Pembayaran simulasi; jangan kirim uang nyata.':''}</p><button class="btn" data-action="refresh-account">Refresh status</button>${tx.type==='withdraw'&&['requested','review'].includes(tx.state)?`<button class="btn secondary" data-action="cancel-withdraw" data-id="${esc(tx.id)}">Batalkan permintaan</button>`:''}`);}

 const tx=S.transactions.find(item=>item.id===txid);if(!tx)return;
 const statusLabel={pending:'Menunggu',completed:'Selesai',cancelled:'Dibatalkan'}[tx.status];
 const isPending=tx.status==='pending';
 const actions=isPending?`<p class="receipt-hint">${tx.type==='withdraw'?'Saldo demo telah dicadangkan. Pembatalan mengembalikannya satu kali.':'Saldo bertambah setelah simulasi pembayaran diselesaikan.'}</p><div class="form-actions receipt-actions"><button class="btn receipt-primary" data-action="settle" data-id="${tx.id}" data-status="completed">${tx.method==='Bank Transfer Manual'?'Simulasikan approval':'Simulasikan selesai'}</button><button class="btn secondary" data-action="settle" data-id="${tx.id}" data-status="cancelled">Batalkan demo</button></div>`:`<div class="form-actions receipt-actions">${link('/user/activity','Lihat aktivitas','btn receipt-primary')}<button class="btn secondary" data-action="close">Tutup</button></div>`;
 const body=`<div class="transaction-summary"><span class="transaction-summary-icon">${icon(tx.type==='deposit'?'wallet':'bank')}</span><div><span class="transaction-summary-label">${tx.type==='deposit'?'Deposit Demo':'Withdraw Demo'}</span><strong>${money(tx.amount)}</strong></div><span class="status ${tx.status}">${statusLabel}</span></div><div class="notice transaction-notice">SIMULASI · Tidak ada tagihan, kode pembayaran, atau transfer uang nyata.</div><div class="receipt"><div class="receipt-row"><span>Referensi</span><strong>${esc(tx.id.slice(0,8).toUpperCase())}</strong></div><div class="receipt-row"><span>Jenis</span><strong>${tx.type==='deposit'?'Deposit':'Withdraw'}</strong></div><div class="receipt-row"><span>Metode</span><strong>${esc(tx.method)}</strong></div><div class="receipt-row"><span>Nominal</span><strong>${money(tx.amount)}</strong></div><div class="receipt-row"><span>Status</span><span class="status ${tx.status}">${statusLabel}</span></div></div>${actions}`;
 modal('Detail Transaksi Demo',body,false,'transaction-dialog');
}
function openChat(){if(connected){const launcher=document.getElementById('chatvice-widget-button');if(launcher){launcher.click();return;}return go('/contact');}modal('Live Chat Demo',`<div class="chat-messages">${chatMessages.map(m=>`<div class="chat-bubble ${m.self?'self':''}">${esc(m.text)}</div>`).join('')}</div><form class="chat-form" data-form="chat"><input name="message" placeholder="Tulis pesan demo…" aria-label="Pesan demo" required maxlength="500" autocomplete="off"><button class="btn" aria-label="Kirim pesan demo">${icon('arrow')}</button></form><p class="small-text muted">Balasan otomatis lokal • Tidak dikirim ke customer service.</p>`);const box=overlays.querySelector('.chat-messages');box.scrollTop=box.scrollHeight;}
async function refreshAccount(){S={...S,...await PG.accountState()};S=pinSoftTechFavorites(S);}
async function launchGame(id){try{if(!S.signedIn)return auth();const g=D.games.find(x=>x.id===id);if(!g)return;const r=await PG.api('/launch','POST',{game_id:g.backendId});const url=new URL(r.game.launch_url);if(url.protocol!=='https:')throw Error('Alamat game belum valid');url.hash='playground_launch='+encodeURIComponent(r.token);location.assign(url.href);}catch(e){toast(e.message);}}
async function showHero(index){
 if(!D.banners.length)return;
 const next=(index+D.banners.length)%D.banners.length,request=++heroRequest;
 const slide=document.querySelectorAll('.hero-slide')[next],img=slide?.querySelector('img');
 if(!slide||!img)return;
 // Keep the current banner visible until the requested image is decoded.
 // Hidden lazy images otherwise produce a blank carousel on a slow connection.
 if(typeof img.decode==='function'){try{await img.decode();}catch{return;}}
 if(request!==heroRequest||!slide.isConnected)return;
 heroIndex=next;
 document.querySelectorAll('.hero-slide').forEach((e,i)=>{e.classList.toggle('active',i===heroIndex);e.setAttribute('aria-hidden',String(i!==heroIndex));e.tabIndex=i===heroIndex?0:-1;});
 document.querySelectorAll('.carousel .dot').forEach((e,i)=>{e.classList.toggle('active',i===heroIndex);e.setAttribute('aria-current',String(i===heroIndex));});
}
async function action(button){
 const a=button.dataset.action;
 if(a.startsWith('client-preview-'))return handleClientPreview(button,{render:rerender,modal,toast});
 if(connected){
  try {
   if(a==='verify-email')return modal('Verifikasi email',`<p>Simpan alamat email pada profil terlebih dahulu.</p><form data-form="verify-email">${field('Password saat ini','password','','password','required')}<button class="btn" type="submit">Kirim tautan verifikasi</button><p class="form-error"></p></form>`);
   if(a==='claim-campaign'){button.disabled=true;try{await PG.api('/rewards/claim','POST',{campaign_id:button.dataset.id});await refreshAccount();rerender();return toast('Bonus sudah masuk ke wallet Playground.');}finally{button.disabled=false;}}
   if(a==='refresh-account'){await refreshAccount();closeModal();return rerender();}
   if(a==='read-all'||a==='message'){const ids=a==='read-all'?S.messages.map(m=>m.id):[...S.messages.filter(m=>m.read).map(m=>m.id),button.dataset.id];await Promise.all(S.messages.filter(m=>m.source==='inbox'&&ids.includes(m.id)&&!m.read).map(m=>PG.api('/inbox/'+m.id+'/read','POST',{})));await PG.api('/preferences','PUT',{favorites:S.favorites,read_messages:ids.filter(id=>!S.messages.some(m=>m.id===id&&m.source==='inbox')).slice(0,100)});S.messages.forEach(m=>{if(ids.includes(m.id))m.read=true;});rerender();if(a==='message'){const m=S.messages.find(m=>m.id===button.dataset.id);return modal(m.title,`<p>${esc(m.text)}</p>`);}return;}
   if(a==='favorite'){if(!S.signedIn)return auth();const next=toggleFavorite(S,button.dataset.id);await PG.api('/preferences','PUT',{favorites:next.favorites});S=next;return rerender();}
   if(a==='logout'){await PG.api('/auth/logout','POST',{});PG.clearSession();await refreshAccount();return go('/');}
   if(a==='cancel-withdraw'){await PG.api('/withdrawals/'+button.dataset.id+'/cancel','POST',{});await refreshAccount();closeModal();return rerender();}
   if(['settle','claim-bonus','claim-promo','reset','reset-prompt','provider-preview','poker-preview','fishing-preview'].includes(a))return toast('Fitur ini belum diaktifkan oleh Playground.');
   if(a==='launch-demo'||a==='resume-game')return launchGame(button.dataset.id);
  } catch(e){return toast(e.message);}
 }

 if(a==='close')return closeModal();
 if(a==='drawer')return drawer();
 if(a==='auth')return auth(button.dataset.mode);
 if(a==='chat')return openChat();
 if(a==='hero-step')return showHero(heroIndex+Number(button.dataset.direction));
 if(a==='hero-dot')return showHero(Number(button.dataset.index));
 if(a==='special'){specialIndex=Number(button.dataset.index);return rerender();}
 if(a==='rail'){button.closest('.provider-section').querySelector('.rail').scrollBy({left:Number(button.dataset.direction)*300,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}
 if(a==='favorite'){S=toggleFavorite(S,button.dataset.id);save();rerender();return;}
 if(a==='filter-favorites'){const u=current();u.searchParams.get('favorites')?u.searchParams.delete('favorites'):u.searchParams.set('favorites','1');return go(u.pathname+u.search);}
 if(a==='more'){pageLimit+=30;return rerender();}
 if(a==='amount'){const f=button.closest('form');f.elements.amount.value=button.dataset.amount;f.querySelectorAll('[data-action="amount"]').forEach(option=>{const selected=option===button;option.classList.toggle('selected',selected);option.setAttribute('aria-pressed',String(selected));});f.elements.amount.focus();return;}
 if(a==='receipt')return receipt(button.dataset.id);
 if(a==='settle'){const before=S.transactions.find(x=>x.id===button.dataset.id);S=settleTransaction(S,button.dataset.id,button.dataset.status);if(before?.status==='pending')log('Transaksi demo '+button.dataset.status+': '+before.id.slice(0,8));save();rerender();return receipt(button.dataset.id);}
 if(a==='claim-bonus'||a==='claim-promo'){try{S=claimBonus(S,button.dataset.id,a==='claim-bonus'?Number(button.dataset.amount):5000);log('Klaim bonus demo: '+button.dataset.id);save();rerender();toast('Bonus ditambahkan ke saldo demo.');}catch(e){toast(e.message);}return;}
 if(a==='message'){const m=S.messages.find(x=>x.id===button.dataset.id);m.read=true;save();rerender();return modal(m.title,`<p>${esc(m.text)}</p>`);}
 if(a==='read-all'){S.messages.forEach(m=>m.read=true);save();return rerender();}
 if(a==='logout'){log('Keluar dari akun demo');S.signedIn=false;save();go('/');return toast('Anda keluar dari sesi demo.');}
 if(a==='locale'){S.locale=button.dataset.locale;save();closeModal();return rerender();}
 if(a==='freespins')return modal('Free Spins','<p>Tidak ada freespin yang tersedia.</p><p class="small-text muted">Bonus akan disinkronkan setelah integrasi backend Playground.</p>');
 if(a==='copy'){try{await navigator.clipboard.writeText(button.dataset.value);toast('Berhasil disalin.');}catch{modal('Salin teks',`<input readonly value="${esc(button.dataset.value)}" aria-label="Teks untuk disalin"><p class="small-text muted">Pilih teks dan salin secara manual.</p>`);}return;}
 if(a==='provider-preview'){const s=D.sports.find(x=>x.id===button.dataset.id);return modal(s.title,`<div class="preview-game">${image(s.image,s.title)}<h3>${esc(s.title)}</h3><p>Lobby provider dalam mode pratinjau. Integrasi sesi provider dilakukan pada tahap backend.</p></div>`);}
 if(a==='poker-preview'){return go('/play/poker/'+D.games.find(g=>g.family==='poker').id);}
 if(a==='fishing-preview')return modal('Fishing Lobby',`<div class="preview-game">${image(D.illustrations.fishing,'Fishing')}<h3>Fishing</h3><p>Kontainer lobby siap untuk katalog dan sesi provider Playground.</p>${link('/arcade/category/hot','Lihat Arcade','btn')}</div>`);
 if(a==='download-info')return modal('Download Aplikasi','<p>Aplikasi agen belum tersedia pada pratinjau ini.</p><p class="muted">Tombol download siap dikonfigurasi dengan file aplikasi milik agen ketika tersedia.</p>');
 if(a==='dismiss-continue'){S=dismissLastGame(S);save();renderContinuePlaying();return;}
 if(a==='launch-demo'||a==='resume-game'){const g=D.games.find(x=>x.id===button.dataset.id);if(!g)return;if(a==='resume-game')go('/play/'+g.family+'/'+g.id);rememberPlayed(g);log('Preview game: '+g.title);return modal(g.title,`<div class="preview-game">${image(g.image,g.title)}<h3>Sesi preview siap</h3><p>Alur pembukaan game berhasil dan sudah dicatat di histori demo.</p><span class="demo-chip">TANPA TARUHAN · TANPA UANG NYATA</span><div class="form-actions" style="justify-content:center">${link('/user/history','Lihat histori','btn secondary')}<button class="btn" data-action="close">Kembali ke game</button></div></div>`,true);}
 if(a==='reset-prompt')return modal('Reset Data Demo','<p>Hapus perubahan lokal dan kembalikan akun, saldo, favorit serta histori ke kondisi awal demo?</p><div class="form-actions"><button class="btn" data-action="reset">Reset demo</button><button class="btn secondary" data-action="close">Batal</button></div>');
 if(a==='reset'){S=pinSoftTechFavorites(initialState());save();go('/');return toast('Data demo dikembalikan ke kondisi awal.');}
}
document.addEventListener('click',e=>{
 const original=e.target.closest('a[data-original-play]');if(original){if(connected){e.preventDefault();launchGame(original.dataset.originalPlay);return;}const g=D.games.find(x=>x.id===original.dataset.originalPlay);if(g){rememberPlayed(g);log('Buka game original: '+g.title);}return;}
 const b=e.target.closest('[data-action]');if(b){e.preventDefault();action(b).catch(error=>toast(error.message||'Aksi belum berhasil.'));return;}
 const quick=e.target.closest('.account-quick-actions a[data-account-section]');if(quick&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&e.button===0){e.preventDefault();const target=quick.dataset.accountSection;if(path()==='/user'&&focusAccountSection(target)){history.replaceState({},'', '/user#account-'+target);return;}go('/user#account-'+target,{section:target});return;}
  const a=e.target.closest('a[data-route]');if(a&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&e.button===0){e.preventDefault();if(swipeIgnore){swipeIgnore=false;return;}go(a.getAttribute('href'));return;}
 if(e.target.hasAttribute('data-overlay'))closeModal();
});
document.addEventListener('input',e=>{if(e.target.matches('[data-form="transaction"] [name="amount"]')){const form=e.target.closest('form');form.querySelectorAll('[data-action="amount"]').forEach(button=>{const selected=Number(button.dataset.amount)===Number(e.target.value);button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected));});}});
document.addEventListener('change',e=>{if(e.target.matches('[data-filter-provider]')){const family=e.target.dataset.family;go(e.target.value?'/'+family+'/provider/'+encodeURIComponent(e.target.value):'/'+family+'/category/'+(family==='casino'?'lobby':'hot'));}});
document.addEventListener('submit',async e=>{
 const form=e.target.closest('[data-form]');if(!form)return;e.preventDefault();const f=new FormData(form),formType=form.dataset.form;const err=form.querySelector('.form-error');if(err)err.textContent='';
 if(form.dataset.busy==='1')return;
 form.dataset.busy='1';const submit=form.querySelector('[type="submit"]');if(submit)submit.disabled=true;
 try{
  if(connected&&formType==='verify-email'){const r=await PG.api('/email/request','POST',{password:f.get('password')});return modal('Verifikasi email',`<p>${esc(r.message)}</p>`);}
  if(connected&&formType==='recovery'){const r=await PG.api('/auth/recovery','POST',{username:f.get('username')});return modal('Permintaan pemulihan',`<p>${esc(r.message)}</p><button class="btn" data-action="chat">Hubungi dukungan</button>`);}
  if(connected&&['auth','profile','transaction','support','password'].includes(formType)){
    if(formType==='auth'){
      if(form.dataset.mode==='register'&&f.get('password')!==f.get('confirm'))throw Error('Konfirmasi password tidak sama.');
      await PG.authenticate(form.dataset.mode,{username:f.get('username'),password:f.get('password'),referral_code:f.get('referral_code')||undefined});await refreshAccount();go('/user');return;
    }
    if(!S.signedIn)return auth();
    if(formType==='profile'){await PG.api('/profile','PUT',{name:f.get('name'),email:f.get('email')});await refreshAccount();rerender();return toast('Profil tersimpan di Playground.');}
    if(formType==='password'){await PG.api('/auth/password','POST',{current_password:f.get('current_password'),password:f.get('password')});PG.clearSession();await refreshAccount();rerender();return auth();}
    if(formType==='transaction'){
      const key=form.dataset.requestKey||(form.dataset.requestKey=id());
      const payload={amount:f.get('amount'),idempotency_key:key};
      if(form.dataset.type==='deposit')payload.method={'QRIS':'qris','Virtual Account':'va','Bank Transfer Manual':'manual'}[f.get('method')];
      else payload.beneficiary=String(f.get('bank'))+' '+String(f.get('account'));
      const tx=await PG.api(form.dataset.type==='deposit'?'/deposits':'/withdrawals','POST',payload);delete form.dataset.requestKey;
      await refreshAccount();rerender();return receipt(tx.id);
    }
    const ticket=await PG.api('/tickets','POST',{subject:f.get('subject'),body:f.get('message')});await refreshAccount();return modal('Tiket terkirim',`<p>Nomor tiket: ${esc(ticket.id)}</p><p>Pesan sudah masuk ke dashboard agen Playground.</p>`);
  }
  if(formType==='search'){const u=current();u.searchParams.set('q',String(f.get('q')).trim());if(path()==='/')u.pathname='/search';go(u.pathname+u.search);}
  if(formType==='auth'){const mode=form.dataset.mode;if(mode==='forgot'){modal('Reset Demo Disimulasikan','<p>Alur permintaan reset berhasil disimulasikan.</p><p class="muted">Tidak ada email atau password akun nyata yang diubah. Untuk masuk kembali, gunakan password demo <strong>demo1234</strong>.</p><button class="btn" data-action="auth" data-mode="login">Kembali ke login</button>');return;}if(mode==='login'&&f.get('password')!=='demo1234')throw new Error('Gunakan password demo: demo1234.');if(mode==='register'&&f.get('password')!==f.get('confirm'))throw new Error('Konfirmasi password tidak sama.');if(mode==='register'){S=pinSoftTechFavorites(initialState());S.user.email=String(f.get('email'));}S.user.name=String(f.get('username'));S.signedIn=true;log(mode==='login'?'Masuk akun demo':'Registrasi akun demo');save();go('/user');toast(mode==='login'?'Berhasil masuk ke akun demo.':'Akun demo dibuat. Password login demo: demo1234.');}
  if(formType==='profile'){S.user={...S.user,name:String(f.get('name')),email:String(f.get('email'))};log('Profil demo diperbarui');save();rerender();toast('Profil demo tersimpan.');}
  if(formType==='transaction'){const txid=id();S=createTransaction(S,{type:form.dataset.type,amount:f.get('amount'),method:String(f.get('method')),id:txid,now:new Date().toISOString()});log('Pengajuan '+form.dataset.type+' demo: '+txid.slice(0,8));save();rerender();receipt(txid);}
  if(formType==='activity-filter')go('/user/activity?type='+encodeURIComponent(f.get('type'))+'&status='+encodeURIComponent(f.get('status')));
  if(formType==='support'){const ticket='DEMO-'+id().slice(0,8).toUpperCase();S.messages.unshift({id:ticket,title:ticket+' · '+String(f.get('subject')),text:'Tiket demo lokal tersimpan: '+String(f.get('message')),read:false});log('Tiket bantuan demo '+ticket);save();form.reset();modal('Tiket Demo Tersimpan',`<p>Nomor tiket: <strong>${ticket}</strong></p><p class="muted">Pesan hanya tersimpan di browser ini. Tidak dikirim ke pihak lain.</p>${link('/user/messages','Lihat Inbox','btn')}`);}
  if(formType==='chat'){const text=String(f.get('message')).trim();if(!text)return;chatMessages.push({self:true,text});const lower=text.toLowerCase();chatMessages.push({self:false,text:lower.includes('deposit')?'Buka menu Deposit, pilih metode dan nominal, lalu coba tombol Simulasikan selesai pada detail transaksi.':lower.includes('withdraw')?'Buka Withdraw. Saldo demo dicadangkan saat pengajuan; jika dibatalkan, saldo dikembalikan satu kali.':lower.includes('bonus')?'Buka Bonus di menu akun. Setiap bonus demo hanya dapat diklaim satu kali.':'Terima kasih. Ini adalah balasan demo lokal. Anda dapat mencoba pencarian game, favorit, promosi, atau workflow member dari menu.'});openChat();}
  if(formType==='lotto-history'){document.querySelector('#lotto-history-body').innerHTML=`<tr><td>${esc(f.get('date'))}</td><td>Totomacau Pools</td><td>8179 <span class="demo-chip">DATA CONTOH</span></td></tr>`;toast('Filter tanggal contoh diterapkan.');}
 }catch(error){if(err)err.textContent=error.message;else toast(error.message);}
 finally{delete form.dataset.busy;if(submit)submit.disabled=false;}
});
document.addEventListener('keydown',e=>{
 if(e.key==='Escape'){closeModal();return;}
 if(e.key==='Tab'&&overlays.firstElementChild){const focusable=[...overlays.querySelectorAll('button:not(:disabled),a,input,select,textarea,[tabindex="0"]')].filter(x=>x.offsetParent!==null);const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}
});
document.addEventListener('error',e=>{if(e.target.tagName==='IMG'&&!e.target.dataset.fallback){e.target.dataset.fallback='true';e.target.src=D.games[0]?.image||'/assets/soft-tech/soft-tech-originals-hero-v1.webp';}},true);
let swipeStart=null,swipeIgnore=false;
document.addEventListener('pointerdown',e=>{if(e.target.closest('.carousel'))swipeStart={x:e.clientX,y:e.clientY};});
document.addEventListener('pointerup',e=>{if(!swipeStart)return;const dx=e.clientX-swipeStart.x,dy=e.clientY-swipeStart.y;swipeStart=null;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)){showHero(heroIndex+(dx<0?1:-1));swipeIgnore=true;setTimeout(()=>swipeIgnore=false,200);}});
window.addEventListener('popstate',()=>{closeModal();pageLimit=30;render();});
setInterval(()=>{if(!document.hidden&&!overlays.firstElementChild&&!matchMedia('(prefers-reduced-motion: reduce)').matches&&document.querySelector('.carousel')&&!document.querySelector('.carousel:hover')&&!document.querySelector('.carousel:focus-within'))showHero(heroIndex+1);},6000);
setInterval(()=>{document.querySelectorAll('[data-countdown]').forEach(el=>{const seconds=3600-Math.floor(Date.now()/1000)%3600;el.textContent='00:'+String(Math.floor(seconds/60)%60).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');});},1000);
if(path()==='/en'){S.locale='en';save();history.replaceState({},'','/');}
if(!S.lastPlayed){
 const previous=S.activity.find(a=>typeof a?.text==='string'&&/^(Preview game:|Buka game original:) /.test(a.text));
 const previousGame=previous&&D.games.find(g=>g.title===previous.text.replace(/^(Preview game:|Buka game original:) /,''));
 if(previousGame){S=rememberGame(S,previousGame.id,previous.time);save();}
}
render();

if(connected){setInterval(async()=>{if(S.signedIn&&!document.hidden){try{await refreshAccount();if(!document.querySelector('form:focus-within')&&!overlays.firstElementChild)rerender();}catch(e){toast(e.message);}}},15000);}

